{
  "name": "TCP值客户端",
  "name_en": "TCP Value Client",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，通过 TCP 在局域网中连接值服务端并读取远程发送的数据。它适用于实验系统之间传递传感器读数、控制量或状态值，而不是直接控制某一台具体实验仪器。",
  "description_en": "This is a non-physical software component that connects to a value server over TCP on a local network and reads remotely transmitted data. It is used to pass sensor readings, control values, or status values between experiment systems rather than directly controlling a specific laboratory instrument.",
  "actions": [
    {
      "action_name": "auto-is_connected",
      "description": "获取TCP客户端是否已连接",
      "description_en": "get whether the TCP client is connected"
    },
    {
      "action_name": "auto-read",
      "description": "读取套接字中的值数据",
      "description_en": "read value data from the socket"
    },
    {
      "action_name": "auto-reset",
      "description": "重置TCP客户端连接状态",
      "description_en": "reset the TCP client connection state"
    },
    {
      "action_name": "auto-run",
      "description": "运行客户端并接收网络值消息",
      "description_en": "run the client and receive value messages over TCP"
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭TCP客户端",
      "description_en": "shut down the TCP client"
    }
  ],
  "tag_hints": [
    "TCP client",
    "network value transport",
    "local network messaging",
    "remote data subscription",
    "experiment system integration",
    "non-physical software component"
  ]
}

